typst_code:
#set page(
  paper: "a5",
  flipped: true,
  margin: 0mm,
  background: [
    #place(top + left,
        dx: 5mm,
        dy: 5mm,
        // This is only a sample image. Upload your image to the private file to use it
        // Remember to use the exact name (including the hash if there is any).
        // crispy_image("ManagerLogo.svg", width: 28.5mm)
        "Company Logo"
    ),
    #place(top + right,
        dx: -5mm,
        dy: 5mm,
        // crispy_image("wsqg_address.svg", width: 34.5mm)
    )[Company address and contacts]
  ]
)

#let sunderline = (thickness: 0.25mm, dash: (0.1mm, 0.5mm), cap: "round", join: "round")

// Payment Type
#if doc.payment_type == "Receive" {
	place(top + center, dx: 0mm, dy: 10mm)[
		#text(lang: "ar", "ســــــــــنــــــــــد قـــــبــــــــــض", font: "Muna", size:19pt, weight: 600)
	]
	place(top + center, dx: 0mm, dy: 18.5mm)[
		#text(lang: "ar", "Receipt Voucher", font: "Rajdhani", size:14pt, weight: 700)
	]
} else {
	place(top + center, dx: 0mm, dy: 10mm)[
		#text(lang: "ar", "ســــــــــنــــــــــد صـــــرف", font: "Muna", size:19pt, weight: 600)
  	]
	place(top + center, dx: 0mm, dy: 18.5mm)[
		#text(lang: "ar", "Payment Voucher", font: "Rajdhani", size:14pt, weight: 700)
	]
}

// LAYOUT ELEMENT
#place(top + left, dx: 5mm, dy: 47.5mm)[
	#rect(radius: 8mm, width: 200mm, height: 95.5mm, stroke: 0.25pt)
]
#place(top + left, dx: 13mm, dy: 41.5mm)[
	#rect(
		radius: 2mm,
		width: 42mm,
		height: 12mm,
		stroke: 1pt,
		fill: rgb("#f1f2f2")
	)
]

#place(top + right, dx: -12mm, dy: 41.5mm)[
	#rect(
		radius: 2mm,
		width: 58mm,
		height: 12mm,
		stroke: 1pt,
		fill: rgb("#f1f2f2")
	)
]
#place(top + left, dx: 15mm, dy: 38.4mm)[
	#text("Kuwaiti Dinar", font: "Rajdhani", size:8pt, weight: 700)
]
#place(top + left, dx: 41mm, dy: 38.3mm)[
	#text(lang: "ar", "دينار كويتي", font: "Muna", size:8pt, weight: 900)
]

// BODY
// Field: Voucher No.
#place(
	top + right,
	dx: -8mm,
	dy: 41.5mm
)[
	#rect(
		radius: 0mm,
		width: 65mm,
		height: 12mm,
		stroke: 0pt,
		text(font: "Oswald", size: 18pt, red, weight: 500, tracking: 0pt)[
			#align(horizon + center)[#doc.name]
		]
	)
]


#let amount = doc.received_amount.replace("KWD ", "")



#place(top + left, dx: 13mm, dy: 42mm)[
	#rect(
		width: 42mm,
		height: 11mm,
		stroke: 0pt,
		text(font: "Shippori Mincho", size: 18pt , weight: 700, red)[
			#align(horizon + right)[#amount]
		]
)]

#place(top + right, dx: -7mm, dy: 58mm)[
	#text(lang: "ar", "التاريخ", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 154mm, dy: 59mm)[
	#text("Date", font: "Eurostile", size:10pt, weight: "regular")
]
// Field: Date
#place(top + left, dx: 163mm, dy: 56.6mm)[
	#rect(
		radius: 0mm,
		width: 28mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#align(center)[#text(font: "Inter", size:14pt, weight: 400, fill: rgb("#0000cc"))[#doc.posting_date]]
		]
]

// RECEIPT START
#place(top + right, dx: -7mm, dy: 68mm)[
	#text(lang: "ar", "وصلنا من السادة", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 7mm, dy: 69mm)[
	#text("Received from M/S", font: "Eurostile", size:10pt, weight: "regular")
]
#place(top + left, dx: 38mm, dy: 66.7mm)[
	#rect(
		radius: 0mm,
		width: 138mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#text(font: "Inter", size:14pt, weight: 600, fill: rgb("#0000cc"))[#doc.party_name]
		]
]

#place(top + right, dx: -7mm, dy: 78mm)[
	#text(lang: "ar", "مبلغ و قدره د.ك.", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 7mm, dy: 79mm)[
	#text("The Sum of", font: "Eurostile", size:10pt, weight: "regular")
]
// Field: Amount in Words
#place(top + left, dx: 30mm, dy: 76.7mm)[
	#rect(
		radius: 0mm,
		width: 141mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#text(font: "Inter", size:10pt, weight: 600, fill: rgb("#0000cc"))[#doc.in_words]
		]
]
// Method of Payment
#place(top + right, dx: -7mm, dy: 88mm)[
	#text(lang: "ar", "طريقة الدفع", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 128mm, dy: 89mm)[
	#text("Method", font: "Eurostile", size:10pt, weight: "regular")
]

// Field: Method of Payment
#place(top + left, dx: 141mm, dy: 86.7mm)[
	#rect(
		radius: 0mm,
		width: 41mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#align(center)[#text(font: "Inter", size:14pt, weight: 600, fill: rgb("#0000cc"))[#doc.mode_of_payment]]
		]
]
#place(top + right, dx: -84mm, dy: 88mm)[
	#text(lang: "ar", "شيك رقم", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 67mm, dy: 89mm)[
	#text("Cheque No.", font: "Eurostile", size:10pt, weight: "regular")
]
// Field: Cheque Number
#place(top + left, dx: 85mm, dy: 86.7mm)[
	#rect(
		radius: 0mm,
		width: 25mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#align(center)[#text(font: "Inter", size:14pt, weight: "black", fill: rgb("#0000cc"))[]]
		]
]
#place(top + right, dx: -145mm, dy: 88mm)[
	#text(lang: "ar", "بنك", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 7mm, dy: 89mm)[
	#text("Bank", font: "Eurostile", size:10pt, weight: "regular")
]
#place(top + left, dx: 16mm, dy: 86.7mm)[
	#rect(
		radius: 0mm,
		width: 41mm,
		height: 7mm,
		stroke: (bottom: sunderline))[
		#align(center)[#text(lang: "ar", font: "Almohanad long kaf", size:14pt, weight: "black", fill: rgb("#0000cc"))[#doc.bank]]
		]
]
#place(top + right, dx: -7mm, dy: 98mm)[
	#text(lang: "ar", "و ذلك عن", font: "Muna", size:14pt, weight: "regular")
]
#place(top + left, dx: 7mm, dy: 99mm)[
	#text("For", font: "Eurostile", size:10pt, weight: "regular")
]
#place(top + left, dx: 14mm, dy: 103.7mm)[
	#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)
]
#place(top + left, dx: 14mm, dy: 110.7mm)[
	#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)
]
#place(top + left, dx: 14mm, dy: 117.7mm)[
	#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)
]
#place(top + left, dx: 14mm, dy: 96.7mm)[
	#rect(
		radius: 0mm,
		width: 172mm,
		height: 7mm,
		stroke: 0pt)[
		#text(font: "Inter", size:14pt, weight: 400, fill: rgb("#0000cc"))[#doc.remarks]
		]
]

