typst_code:
// ========================================
// USER CUSTOM SECTION
// ✏️ Document formatting, branding, and styling
// ========================================

// Typography styles
#let fieldLabelStyle = (
  font: "Inter 18pt",
  size: 10pt,
  style: "italic",
  weight: 400,
  fill: rgb("64748B")
)

#let fieldValueStyle = (
  font: "Inter 18pt",
  size: 10pt,
  style: "normal",
  weight: 400,
  fill: rgb("0F172A")
)

#let sectionLabelStyle = (
  font: "Inter 18pt",
  size: 12pt,
  style: "normal",
  weight: 600,
  fill: rgb("1E293B")
)

// Table styles
#let tableHeaderStyle = (
  font: "Inter 18pt",
  size: 9pt,
  style: "normal",
  weight: 600,
  fill: rgb("0f172a")
)

#let tableBodyStyle = (
  font: "Inter 18pt",
  size: 9pt,
  style: "normal",
  weight: 400,
  fill: rgb("0f172a")
)

#let tableCellInset = (top: 6pt, right: 2pt, bottom: 6pt, left: 2pt)
#let tableStroke = 0.5pt + rgb("e2e8f0")
#let tableHeaderFill = rgb("f1f5f9")
#let tableStripeFill = rgb("f8fafc")
#let tableStripeEnabled = false

#let header_block = []
#let footer_block = []

// Add your custom styling below

// Sections rendered as a grid.
#set grid(
  inset: (x: 0pt, y: 8pt),
)

// ========================================
// END USER CUSTOM SECTION
// ========================================

// ========================================
// AUTO-GENERATED SECTION
// ⚠️ WARNING: This section is regenerated from Print Format Builder
// ⚠️ Do not edit below - changes will be overwritten!
// ========================================

// Document data dictionary (real document data)
#let doc = (
  name: "ACC-SINV-2026-04953",
  doctype: "Sales Invoice",
  title: "BNG104 F21",
  docstatus: 1,
  owner: "Administrator",
  modified: "2026-01-14 06:55:29.579278",
  customer_name: "BNG104 F21",
  address_display: "Block: 01 • Street: 097 (Bour Said)\nBldg: 104\nBnaid Al-Qar\nAlAsima\n92911054\nKuwait",
  posting_date: "2025-12-29",
  contact_display: "",
  due_date: "2025-12-29",
  contact_mobile: "",
  items: (
    (
      item_code: "STO-26-0007",
      description: "Product 001",
      uom: "Nos",
      qty: "3",
      rate: "KWD 144.404",
      amount: "KWD 433.212",
      name: "h7bo7c7go6",
      idx: "1",
      doctype: "Sales Invoice Item",
      parent: "ACC-SINV-2026-04953",
      parentfield: "items",
      parenttype: "Sales Invoice",
    ),
  ),
  terms: "",
  total: "KWD 433.212",
  taxes: (
  ),
  grand_total: "KWD 433.212",
  rounded_total: "KWD 433.210",
  in_words: "KWD Four Hundred And Thirty Three and Two Hundred And Ten Fils only.",
)

// Document Header
// Here you can palce items belonging to the page header.
// This is only an example you can comment out to check the outcome.
//#let header_block = [ #set text(8pt)
//    #smallcaps[Crispy Print]
//    #h(1fr) _Sales Invoice_
//]

// Document Footer
// Here you can place items belonging to footer.
// The code below will display the page number
// in the footer block right align.
#let footer_block = align(right + horizon)[
  #set text(size: 8pt)
  #context counter(page).display("1 of 1", both: true)
]

// Page setup
#set page(
  paper: "a4",
  margin: (top: 25mm, bottom: 20mm, left: 10mm, right: 10mm),
  header: header_block,
  footer: footer_block,
  background: [
    #place(bottom + left, dx: 10mm, dy: -5mm, image("ACC-SINV-2026-04953-qr.svg", width: 15mm))
  ],
)

// Section: Section 1

#grid(
  columns: (1fr, 1fr),
  align: (left, right),
  stroke: (x, y) => if y == 0 {
    (bottom: (thickness: 0.5pt, cap: "round", paint: rgb("#00519B")))
  },
  [#text(font: "Inter 18pt", size: 14pt, weight: 800)[#doc.doctype]],
  [#text(font: "Veneer Two", size: 18pt, red)[#doc.name]]
)
// Section: Section 2

#grid(
  columns: (2fr, 2fr, 1fr),
  [#text(..fieldLabelStyle)[Customer Name]#linebreak()#text(..fieldValueStyle)[#doc.customer_name]],
  [#text(..fieldLabelStyle)[Date]#linebreak()#text(..fieldValueStyle)[#doc.posting_date]],
  [#text(..fieldLabelStyle)[Payment Due Date]#linebreak()#text(..fieldValueStyle)[#doc.due_date]],
  [#text(..fieldLabelStyle)[Address]#linebreak()#text(..fieldValueStyle)[#doc.address_display]],
  [#text(..fieldLabelStyle)[Contact]#linebreak()#text(..fieldValueStyle)[#doc.contact_display]],
  [#text(..fieldLabelStyle)[Mobile No]#linebreak()#text(..fieldValueStyle)[#doc.contact_mobile]],
)
// Section: Section 3

#grid(
  columns: (1fr),
  // Table: Items
  [#if type(doc.items) == array and doc.items.len() > 0 [
    #table(
      columns: (auto, 1fr, auto, auto, auto, auto),
      align: (left, left, left, right, right, right),
      inset: tableCellInset,
      stroke: tableStroke,
      fill: (x, y) => if y == 0 { tableHeaderFill } else { if tableStripeEnabled and calc.even(y) { tableStripeFill } else { none } },
      table.header([#text(..tableHeaderStyle)[Item]], [#text(..tableHeaderStyle)[Description]], [#text(..tableHeaderStyle)[UOM]], [#text(..tableHeaderStyle)[Quantity]], [#text(..tableHeaderStyle)[Rate]], [#text(..tableHeaderStyle)[Amount]]),
      ..doc.items.map(row => ([#text(..tableBodyStyle)[#row.item_code]], [#text(..tableBodyStyle)[#row.description]], [#text(..tableBodyStyle)[#row.uom]], [#text(..tableBodyStyle)[#row.qty]], [#text(..tableBodyStyle)[#row.rate]], [#text(..tableBodyStyle)[#row.amount]])).flatten(),
    )
  ]],
)
// Section: Section 4

#grid(
  columns: (2fr, 1fr),
  [#text(..fieldLabelStyle)[Terms and Conditions]#linebreak()#text(..fieldValueStyle)[#doc.terms]],
  [#text(..fieldLabelStyle)[Total]#linebreak()#align(right)[#text(..fieldValueStyle)[#doc.total]]],
)
// Section: VAT
#block(spacing: 0.6em)[#text(..sectionLabelStyle)[VAT]]


#grid(
  columns: (1fr),
  // Table: Sales Taxes and Charges
  [#if type(doc.taxes) == array and doc.taxes.len() > 0 [
    #table(
      columns: (1fr, auto, auto, auto),
      align: (left, right, right, right),
      inset: tableCellInset,
      stroke: tableStroke,
      fill: (x, y) => if y == 0 { tableHeaderFill } else { if tableStripeEnabled and calc.even(y) { tableStripeFill } else { none } },
      table.header([#text(..tableHeaderStyle)[Description]], [#text(..tableHeaderStyle)[Tax Rate]], [#text(..tableHeaderStyle)[Amount]], [#text(..tableHeaderStyle)[Total]]),
      ..doc.taxes.map(row => ([#text(..tableBodyStyle)[#row.description]], [#text(..tableBodyStyle)[#row.rate]], [#text(..tableBodyStyle)[#row.tax_amount]], [#text(..tableBodyStyle)[#row.total]])).flatten(),
    )
  ]],
)
// Section: Totals
#block(spacing: 0.6em)[#text(..sectionLabelStyle)[Totals]]


#grid(
  columns: (2fr, 1fr),
  [#none],
  [#text(..fieldLabelStyle)[Grand Total]#linebreak()#align(right)[#text(..fieldValueStyle)[#doc.grand_total]]],
  [#none],
  [#text(..fieldLabelStyle)[Rounded Total]#linebreak()#align(right)[#text(..fieldValueStyle)[#doc.rounded_total]]],
  [#none],
  [#text(..fieldLabelStyle)[In Words]#linebreak()#text(..fieldValueStyle)[#doc.in_words]],
)

// ========================================
// END AUTO-GENERATED SECTION
// ========================================

